/**
 * =============================================================================
 * KAYTX PHONE AGENT PHONE NUMBERS
 * =============================================================================
 * Assigns deterministic mock/placeholder phone numbers to the ~72 phone/caller
 * agents routed from `app/(tabs)/home.tsx` to `/ai-agent/phone`
 * (e.g. `2-cx-phone-receptionist`, `2-sales-phone-negotiator`).
 *
 * These agents are NOT part of the master `agentRegistry` (they are route-map
 * keys without per-agent data objects), so their numbers live here instead.
 * Values are generated by the same helper used for the registry, keeping the
 * format consistent across the app. No real PII is introduced.
 */

import { generateAgentPhoneNumber } from './aiAgentRegistry';

