// Base offset keeps these numbers distinct from the registry's 1..1135 seq range.
const PHONE_AGENT_SEQ_OFFSET = 5000;

/** Map of phone-agent route id -> assigned mock phone number. */
export const PHONE_AGENT_NUMBERS: Record<string, string> = PHONE_AGENT_IDS.reduce(
  (acc, id, idx) => {
    acc[id] = generateAgentPhoneNumber(PHONE_AGENT_SEQ_OFFSET + idx);
    return acc;
  },
  {} as Record<string, string>
);

/** Returns the assigned phone number for a phone-agent route id, or null. */
export function getPhoneAgentNumber(id: string): string | null {
  return PHONE_AGENT_NUMBERS[id] ?? null;
}
